% Hierarchical Classification ML -- Two-Stage PURE CLASSIFICATION System
% Stage 1: Coarse CNN classifies which quadrant (TL, TR, BL, BR)
% Stage 2: Per-quadrant CNN classifies which specific position (R#C#P#)
%
% KEY DIFFERENCE from Hierarchical_ML.m:
%   - Hierarchical_ML.m uses regression (predicts continuous x,y then snaps)
%   - This file uses PURE CLASSIFICATION everywhere
%   - No regression layers, no snap-to-nearest
%   - The CNN directly outputs one of the discrete positions
%
% Grid: 6x6, inner 4x4 used (rows 2-5, cols 2-5)
% Quadrants of inner 4x4:
%   Top-Left:     rows 2-3, cols 2-3  (4 cells x 4 corners = 16 positions)
%   Top-Right:    rows 2-3, cols 4-5  (16 positions)
%   Bottom-Left:  rows 4-5, cols 2-3  (16 positions)
%   Bottom-Right: rows 4-5, cols 4-5  (16 positions)
% Total: 64 positions across 4 quadrants
%
% Input to CNN:  [8 x numFreqPoints x 1]
%   Rows: |S11|, ang(S11), |S21|, ang(S21), |S12|, ang(S12), |S22|, ang(S22)
%%%%%%%%%%%%%

clear; clc; close all;

%% 0. CONFIGURATION
fprintf('=== Hierarchical Classification ML: Two-Stage PURE Classification ===\n\n');

% Define the 4 quadrants
quadrants(1).name = 'Top-Left';
quadrants(1).rows = [2 3];
quadrants(1).cols = [2 3];

quadrants(2).name = 'Top-Right';
quadrants(2).rows = [2 3];
quadrants(2).cols = [4 5];

quadrants(3).name = 'Bottom-Left';
quadrants(3).rows = [4 5];
quadrants(3).cols = [2 3];

quadrants(4).name = 'Bottom-Right';
quadrants(4).rows = [4 5];
quadrants(4).cols = [4 5];

quadNames  = {'TL', 'TR', 'BL', 'BR'};
quadColors = {'c', 'm', 'g', 'y'};

% Sub-position offsets (P1=TL, P2=TR, P3=BR, P4=BL within each cell)
subPosOffsets = [-0.375, -0.375; +0.375, -0.375; +0.375, +0.375; -0.375, +0.375];

% Container image: auto-detect then browse fallback
scriptDir = fileparts(mfilename('fullpath'));
if isempty(scriptDir), scriptDir = pwd; end
containerImagePath = fullfile(scriptDir, 'Butter Box', 'ButterBox.png');
if ~isfile(containerImagePath)
    containerImagePath = 'C:\Users\peter\Desktop\EM Imaging\Butter Box\ButterBox.png';
end
if ~isfile(containerImagePath)
    fprintf('Container image not found automatically.\n');
    [imgFile, imgDir] = uigetfile({'*.png;*.jpg;*.jpeg;*.bmp','Image Files'}, ...
        'Select the container photo (e.g. ButterBox.png)');
    if imgFile ~= 0
        containerImagePath = fullfile(imgDir, imgFile);
    else
        containerImagePath = '';
        fprintf('No image selected -- heatmaps will show without overlay.\n');
    end
else
    fprintf('Container image found: %s\n', containerImagePath);
end

% =====================================================================
%  TUNABLE PARAMETERS -- adjust these to improve training
% =====================================================================
% Stage 1 (Quadrant Classifier)
stage1_LR             = 1e-3;
stage1_BatchSize      = 16;
stage1_Epochs         = 10;
stage1_Conv1Filters   = 32;
stage1_Conv2Filters   = 32;
stage1_FC1Neurons     = 64;
stage1_Dropout        = 0.3;
stage1_LRDropFactor   = 0.5;
stage1_LRDropPeriod   = 5;

% Stage 2 (Per-Quadrant Position Classifier) -- same params for all 4
stage2_LR             = 1e-3;
stage2_BatchSize      = 16;
stage2_Epochs         = 100;
stage2_Conv1Filters   = 32;
stage2_Conv2Filters   = 32;
stage2_FC1Neurons     = 64;
stage2_Dropout        = 0.3;
stage2_LRDropFactor   = 0.5;
stage2_LRDropPeriod   = 30;

% Optimizer
optimTrials_Stage1    = 10;
optimTrials_Quadrant  = 25;

% Live prediction
rollingAvgWindow      = 5;
