%% 1. LOAD TRAINING DATA
fprintf('\n--- 1. Loading Data ---\n');
[matFile, matDir] = uigetfile('*.mat', 'Select the training .mat file');
if isequal(matFile, 0)
    error('No file selected. Exiting.');
end
matPath = fullfile(matDir, matFile);
fprintf('Loading: %s\n', matPath);
loaded = load(matPath);

data          = loaded.data;
baseline      = loaded.baseline;
freq          = loaded.freq;
xyCoords      = loaded.xyCoords;
trialCount    = loaded.trialCount;
numFreqPoints = loaded.numFreqPoints;
if isfield(loaded, 'traceList'),    traceList    = loaded.traceList;    else, traceList    = {}; end
if isfield(loaded, 'numSParamRows'),numSParamRows = loaded.numSParamRows;else, numSParamRows = size(data{1,2},1); end

posLabels = cell(size(data, 1), 1);
for pp = 1:size(data, 1)
    posLabels{pp} = data{pp, 1};
end

numPositions = size(data, 1);
fprintf('Loaded %d positions, %d trials each, %d freq points\n', ...
    numPositions, trialCount, numFreqPoints);

%% 2. BUILD FEATURES & LABELS
fprintf('\n--- 2. Building Features & Classification Labels ---\n');

% First pass: determine which positions fall in each quadrant
keepIdx      = [];
posQuadrant  = [];  % numeric quadrant index (1-4)
posLabelList = {};  % position label like 'R2C3P1'

for p = 1:numPositions
    tokens = regexp(posLabels{p}, 'R(\d+)C(\d+)P(\d+)', 'tokens');
    if isempty(tokens), continue; end
    r = str2double(tokens{1}{1});
    c = str2double(tokens{1}{2});

    % Determine quadrant
    qLabel = 0;
    if r >= 2 && r <= 3 && c >= 2 && c <= 3
        qLabel = 1;  % Top-Left
    elseif r >= 2 && r <= 3 && c >= 4 && c <= 5
        qLabel = 2;  % Top-Right
    elseif r >= 4 && r <= 5 && c >= 2 && c <= 3
        qLabel = 3;  % Bottom-Left
    elseif r >= 4 && r <= 5 && c >= 4 && c <= 5
        qLabel = 4;  % Bottom-Right
    end

    if qLabel > 0
        keepIdx(end+1) = p; %#ok<SAGROW>
        posQuadrant(end+1) = qLabel; %#ok<SAGROW>
        posLabelList{end+1} = posLabels{p}; %#ok<SAGROW>
    end
end

% Ensure all labels are char vectors (not strings) for categorical/unique compatibility
posLabelList = cellstr(posLabelList);

numKeptPos   = length(keepIdx);
totalSamples = numKeptPos * trialCount;
fprintf('Kept %d / %d positions in inner 4x4\n', numKeptPos, numPositions);
for q = 1:4
    nq = sum(posQuadrant == q);
    fprintf('  %s: %d positions (%d samples)\n', quadrants(q).name, nq, nq * trialCount);
end

% Build position labels per quadrant and physical coordinates per quadrant
positionLabelsPerQuad = cell(4, 1);
positionCoordsPerQuad = cell(4, 1);
for q = 1:4
    qMaskPos = (posQuadrant == q);
    labelsInQ = posLabelList(qMaskPos);
    % Convert to cellstr if needed (MATLAB unique requires char vectors for cell arrays)
    if isstring(labelsInQ)
        labelsInQ = cellstr(labelsInQ);
    end
    uniqueLabels = unique(labelsInQ);
    positionLabelsPerQuad{q} = uniqueLabels(:)';  % row cell array

    % Compute physical coords for each unique position label
    coordsInQ = zeros(length(uniqueLabels), 2);
    for i = 1:length(uniqueLabels)
        tok = regexp(uniqueLabels{i}, 'R(\d+)C(\d+)P(\d+)', 'tokens');
        rr = str2double(tok{1}{1});
        cc = str2double(tok{1}{2});
        pp = str2double(tok{1}{3});
        coordsInQ(i, 1) = (cc - 0.5) + subPosOffsets(pp, 1);
        coordsInQ(i, 2) = (rr - 0.5) + subPosOffsets(pp, 2);
    end
    positionCoordsPerQuad{q} = coordsInQ;
    fprintf('  %s unique labels: %d\n', quadNames{q}, length(uniqueLabels));
end

% Build feature arrays and label arrays
TrainingFeatures = zeros(8, numFreqPoints, 1, totalSamples);
quadrantIdx      = zeros(totalSamples, 1);   % numeric quadrant (1-4)
posLabelAll      = cell(totalSamples, 1);     % position label string per sample
posXYAll         = zeros(totalSamples, 2);    % physical coords per sample

sIdx = 0;
nanCount = 0;
for i = 1:numKeptPos
    p = keepIdx(i);
    for t = 1:trialCount
        rawMeas = data{p, t+1};
        % Skip NaN/empty trials (failed measurements or skipped retries)
        if isempty(rawMeas) || any(isnan(rawMeas(:)))
            nanCount = nanCount + 1;
            continue;
        end
        sIdx = sIdx + 1;
        TrainingFeatures(:,:,1,sIdx) = rawMeas - baseline;
        quadrantIdx(sIdx) = posQuadrant(i);
        posLabelAll{sIdx} = posLabelList{i};
        posXYAll(sIdx, :) = xyCoords(p, :);
    end
end
% Trim to actual valid samples
TrainingFeatures = TrainingFeatures(:,:,:,1:sIdx);
quadrantIdx = quadrantIdx(1:sIdx);
posLabelAll = posLabelAll(1:sIdx);
posXYAll = posXYAll(1:sIdx, :);
totalSamples = sIdx;
if nanCount > 0
    fprintf('WARNING: Skipped %d NaN/empty trials.\n', nanCount);
end
fprintf('Valid training samples: %d\n', sIdx);

% Ensure char vectors for categorical compatibility
posLabelAll = cellstr(posLabelAll);

% Build categorical labels
quadrantLabelsCat = categorical(quadrantIdx, [1 2 3 4], quadNames);

% Build per-sample position labels as categorical (per quadrant)
posLabelCatPerQuad = cell(totalSamples, 1);  % will hold categorical label per sample
for s = 1:totalSamples
    q = quadrantIdx(s);
    posLabelCatPerQuad{s} = categorical({posLabelAll{s}}, positionLabelsPerQuad{q});
end

fprintf('Training tensor: [%s], %d samples\n', num2str(size(TrainingFeatures)), totalSamples);

%% 3. SPLIT DATA (75/25 stratified)
fprintf('\n--- 3. Splitting Data (75/25 stratified) ---\n');
rng(42);

trainMask = false(totalSamples, 1);
testMask  = false(totalSamples, 1);

for q = 1:4
    qIdx = find(quadrantIdx == q);
    nq = length(qIdx);
    nqTrain = round(0.75 * nq);
    perm = randperm(nq);
    trainMask(qIdx(perm(1:nqTrain))) = true;
    testMask(qIdx(perm(nqTrain+1:end))) = true;
end

XTrain = TrainingFeatures(:,:,:,trainMask);
XTest  = TrainingFeatures(:,:,:,testMask);
YQuadTrain = quadrantLabelsCat(trainMask);
YQuadTest  = quadrantLabelsCat(testMask);
quadTrainIdx = quadrantIdx(trainMask);
quadTestIdx  = quadrantIdx(testMask);
posLabelTrain = posLabelAll(trainMask);
posLabelTest  = posLabelAll(testMask);
posXYTest     = posXYAll(testMask, :);

fprintf('Train: %d samples | Test: %d samples\n', sum(trainMask), sum(testMask));
for q = 1:4
    fprintf('  %s: %d train, %d test\n', quadNames{q}, ...
        sum(quadTrainIdx == q), sum(quadTestIdx == q));
end

%% 4. TRAIN STAGE 1: QUADRANT CLASSIFIER
fprintf('\n--- 4. Training Stage 1: Quadrant Classifier ---\n');

% Auto-detect GPU/parallel for training
if gpuDeviceCount > 0
    execEnv = 'gpu';
    fprintf('GPU detected (%s) -- training will use GPU.\n', gpuDevice().Name);
elseif ~isempty(gcp('nocreate'))
    execEnv = 'parallel';
    fprintf('Parallel pool active (%d workers) -- training will use parallel CPU.\n', gcp().NumWorkers);
else
    execEnv = 'cpu';
    fprintf('Training on single CPU.\n');
end

classLayers1 = [
    imageInputLayer([8 numFreqPoints 1], 'Normalization', 'zscore', 'Name', 'input')

    convolution2dLayer([4 20], stage1_Conv1Filters, 'Padding', 'same', 'Name', 'conv1')
    batchNormalizationLayer('Name', 'bn1')
    reluLayer('Name', 'relu1')

    convolution2dLayer([2 10], stage1_Conv2Filters, 'Padding', 'same', 'Name', 'conv2')
    batchNormalizationLayer('Name', 'bn2')
    reluLayer('Name', 'relu2')

    fullyConnectedLayer(stage1_FC1Neurons, 'Name', 'fc1')
    batchNormalizationLayer('Name', 'bn3')
    reluLayer('Name', 'relu3')
    dropoutLayer(stage1_Dropout, 'Name', 'dropout')

    fullyConnectedLayer(4, 'Name', 'fc_out')
    softmaxLayer('Name', 'softmax')
    classificationLayer('Name', 'output')
];

classOptions1 = trainingOptions('adam', ...
    'MaxEpochs', stage1_Epochs, ...
    'MiniBatchSize', stage1_BatchSize, ...
    'InitialLearnRate', stage1_LR, ...
    'LearnRateSchedule', 'piecewise', ...
    'LearnRateDropPeriod', stage1_LRDropPeriod, ...
    'LearnRateDropFactor', stage1_LRDropFactor, ...
    'Shuffle', 'every-epoch', ...
    'ValidationData', {XTest, YQuadTest}, ...
    'ValidationFrequency', 10, ...
    'ExecutionEnvironment', execEnv, ...
    'Verbose', true, ...
    'Plots', 'training-progress');

coarseNet = trainNetwork(XTrain, YQuadTrain, classLayers1, classOptions1);
fprintf('Stage 1 training complete.\n');

% Evaluate Stage 1
predQuadTest = classify(coarseNet, XTest);
stage1Acc = mean(predQuadTest == YQuadTest) * 100;
fprintf('Stage 1 Quadrant Classification Accuracy: %.1f%%\n', stage1Acc);

% Confusion matrix for Stage 1
figure('Name', 'Stage 1 - Quadrant Confusion Matrix', 'Position', [100 200 500 400]);
confMat1 = confusionmat(YQuadTest, predQuadTest);
confusionchart(confMat1, {quadrants(1).name, quadrants(2).name, ...
