title(sprintf('Stage 1 Quadrant Classifier | Accuracy: %.1f%%', stage1Acc));

%% 5. TRAIN STAGE 2: QUADRANT POSITION CLASSIFIERS
fprintf('\n--- 5. Training Stage 2: Per-Quadrant Position Classifiers ---\n');

quadrantNets = cell(4, 1);

for q = 1:4
