    quadrantNets{q} = trainNetwork(XqTrain, YqTrain, classLayersQ, classOptionsQ);

    % Evaluate
    predQ = classify(quadrantNets{q}, XqTest);
    qAcc = mean(predQ == YqTest) * 100;
    fprintf('    %s Position Accuracy: %.1f%%\n', quadrants(q).name, qAcc);
end

fprintf('\nAll 4 quadrant position classifiers trained.\n');

