    for trial = 1:optimTrials_Stage1
        % Random sample from search space
        p1.InitialLearnRate = 10^(-4 + 3*rand);  % [1e-4, 1e-1] log
        p1.MiniBatchSize = randi([8, 64]);
        p1.Conv1Filters = randi([16, 64]);
        p1.Conv2Filters = randi([16, 64]);
        p1.FC1Neurons = randi([32, 256]);
        p1.Dropout1 = 0.1 + 0.4*rand;
        p1.LearnRateDropFactor = 0.3 + 0.5*rand;

        obj = trainEvalClassifier(p1, XTrain, YQuadTrain, XTest, YQuadTest, numFreqPoints, srchEp1);
        fprintf('  Stage 1 trial %d/%d: objective=%.4f (accuracy=%.1f%%)\n', ...
            trial, optimTrials_Stage1, obj, (1-obj)*100);

        if obj < bestObj1
            bestObj1 = obj;
            bp1 = p1;
        end
        if obj == 0
            fprintf('  100%% accuracy reached — stopping Stage 1 search early.\n');
            break;
        end
    end
    % Convert struct to table for display
    bp1 = struct2table(bp1);
    bp1 = bp1(1,:);  % ensure single row
    fprintf('\nBest Stage 1 params:\n');
