        convolution2dLayer([4 20], bp1.Conv1Filters, 'Padding', 'same', 'Name', 'conv1')
        batchNormalizationLayer('Name', 'bn1')
        reluLayer('Name', 'relu1')
        convolution2dLayer([2 10], bp1.Conv2Filters, 'Padding', 'same', 'Name', 'conv2')
        batchNormalizationLayer('Name', 'bn2')
        reluLayer('Name', 'relu2')
        fullyConnectedLayer(bp1.FC1Neurons, 'Name', 'fc1')
        batchNormalizationLayer('Name', 'bn3')
        reluLayer('Name', 'relu3')
        dropoutLayer(bp1.Dropout1, 'Name', 'dropout')
        fullyConnectedLayer(4, 'Name', 'fc_out')
