        'Verbose', true, ...
        'Plots', 'training-progress');
    coarseNet = trainNetwork(XTrain, YQuadTrain, bestClassLayers1, bestClassOpts1);
    predQuadTest = classify(coarseNet, XTest);
    stage1Acc = mean(predQuadTest == YQuadTest) * 100;
    fprintf('Optimized Stage 1 accuracy: %.1f%%\n', stage1Acc);
end

% --- Stage 2 Optimization ---
optResp2 = input('Run Bayesian optimization for Stage 2 quadrant classifiers? (y/n) [n]: ', 's');
if strcmpi(optResp2, 'y')
    if ~exist('quadrantNets', 'var'), quadrantNets = cell(4, 1); end
    optimVars2 = [
