        quadrantNets{q} = trainNetwork(XqTr, YqTr, bestLayersQ, bestOptsQ);

        predQ = classify(quadrantNets{q}, XqTe);
        qAcc = mean(predQ == YqTe) * 100;
        fprintf('%s optimized accuracy: %.1f%%\n', quadrants(q).name, qAcc);
    end
    fprintf('\nAll 4 optimized quadrant classifiers trained.\n');
end

