%% 8. EVALUATE -- CONFUSION MATRICES
fprintf('\n--- 8. Evaluating Hierarchical Classification System ---\n');

nTest = sum(testMask);
hierQuadChoice   = zeros(nTest, 1);
hierQuadProbs    = zeros(nTest, 4);
hierPosLabel     = cell(nTest, 1);
hierPosProbs     = cell(nTest, 1);
hierPosConfidence = zeros(nTest, 1);

for s = 1:nTest
    testSample = XTest(:,:,:,s);

    % Stage 1: classify quadrant
    quadProbs = predict(coarseNet, testSample);
    [~, quadChoice] = max(quadProbs);
    hierQuadChoice(s) = quadChoice;
    hierQuadProbs(s, :) = quadProbs;

    % Stage 2: classify position within chosen quadrant
    posProbs = predict(quadrantNets{quadChoice}, testSample);
    [posConf, posIdx] = max(posProbs);
    hierPosLabel{s} = positionLabelsPerQuad{quadChoice}{posIdx};
    hierPosProbs{s} = posProbs;
    hierPosConfidence(s) = posConf;
end

% Stage 1 accuracy
stage1Correct = (hierQuadChoice == quadTestIdx);
stage1AccFinal = mean(stage1Correct) * 100;
fprintf('Stage 1 Quadrant Accuracy: %.1f%%\n', stage1AccFinal);

% Overall position accuracy (exact label match)
posCorrect = zeros(nTest, 1);
for s = 1:nTest
    posCorrect(s) = strcmp(hierPosLabel{s}, posLabelTest{s});
end
overallPosAcc = mean(posCorrect) * 100;
fprintf('Overall Position Accuracy (exact match): %.1f%%\n', overallPosAcc);

% Per-quadrant breakdown
fprintf('\nPer-Quadrant Breakdown:\n');
fprintf('  %-12s  Stage1%%  PosAcc%%\n', 'Quadrant');
fprintf('  %s\n', repmat('-', 1, 35));
for q = 1:4
    qMask = (quadTestIdx == q);
    qS1 = mean(hierQuadChoice(qMask) == q) * 100;
    qPosCorr = mean(posCorrect(qMask)) * 100;
    fprintf('  %-12s  %5.1f%%   %5.1f%%\n', quadrants(q).name, qS1, qPosCorr);
end

% ---- Confusion Matrix 1: Stage 1 (4x4 quadrant) ----
figure('Name', 'HierClass - Stage 1 Quadrant Confusion', ...
    'Position', [100 150 600 500]);
confMat1 = confusionmat(categorical(quadTestIdx, 1:4, quadNames), ...
    categorical(hierQuadChoice, 1:4, quadNames));
confMat1Pct = zeros(4, 4);
for i = 1:4
    rowSum = sum(confMat1(i,:));
    if rowSum > 0
        confMat1Pct(i,:) = confMat1(i,:) / rowSum * 100;
    end
end
imagesc(confMat1Pct);
navyRGB = [0.106 0.165 0.290]; tealRGB = [0.051 0.486 0.561]; whiteRGB = [1 1 1];
n = 256; cmap = zeros(n, 3);
for ci = 1:n, t = (ci-1)/(n-1); if t < 0.5, frac = t/0.5; cmap(ci,:) = navyRGB*(1-frac) + tealRGB*frac; else, frac = (t-0.5)/0.5; cmap(ci,:) = tealRGB*(1-frac) + whiteRGB*frac; end; end
colormap(gca, cmap);
cbar = colorbar;
cbar.Label.String = 'Prediction Rate (%)';
cbar.Label.Color = [1 1 1]; cbar.Color = [1 1 1];
caxis([0 100]);
set(gcf, 'Color', [0.106 0.165 0.290]);
set(gca, 'Color', [0.106 0.165 0.290], 'XColor', [1 1 1], 'YColor', [1 1 1]);
set(gca, 'XTick', 1:4, 'XTickLabel', {quadrants(1).name, quadrants(2).name, ...
    quadrants(3).name, quadrants(4).name});
set(gca, 'YTick', 1:4, 'YTickLabel', {quadrants(1).name, quadrants(2).name, ...
    quadrants(3).name, quadrants(4).name});
xlabel('PREDICTED Quadrant', 'FontWeight', 'bold', 'Color', [1 1 1]);
ylabel('TRUE Quadrant', 'FontWeight', 'bold', 'Color', [1 1 1]);
title(sprintf('Stage 1 Quadrant Confusion | Accuracy: %.1f%% | Overall Pos: %.1f%%', ...
    stage1AccFinal, overallPosAcc), 'FontWeight', 'bold', 'Color', [1 1 1]);
for i = 1:4
    for j = 1:4
        if confMat1Pct(i,j) > 0
            if confMat1Pct(i,j) > 50, txtColor = [0.106 0.165 0.290]; else, txtColor = [1 1 1]; end
            text(j, i, sprintf('%.0f%%', confMat1Pct(i,j)), ...
                'HorizontalAlignment', 'center', 'FontSize', 12, ...
                'Color', txtColor, 'FontWeight', 'bold');
        end
    end
end
hold on;
plot([0.5 4.5], [0.5 4.5], 'Color', [0.051 0.486 0.561], 'LineStyle', '--', 'LineWidth', 1.5);
hold off;

% ---- Confusion Matrices 2-5: Per-Quadrant Position ----
fprintf('\n--- Per-Quadrant Position Confusion Matrices ---\n');
for q = 1:4
    qMask = (quadTestIdx == q);
    qTrueLabels = posLabelTest(qMask);
    qPredLabels = hierPosLabel(qMask);
    uniqueQ = positionLabelsPerQuad{q};
    nQPos = length(uniqueQ);

    if nQPos == 0 || sum(qMask) == 0
        fprintf('  %s: No test samples, skipping.\n', quadrants(q).name);
        continue;
    end

    % Build confusion matrix
    qTrueCat = categorical(qTrueLabels, uniqueQ);
    qPredCat = categorical(qPredLabels, uniqueQ);

    % Some predictions may be from wrong quadrant (Stage 1 error)
    % Those will be <undefined> -- count them separately
    validPred = ~isundefined(qPredCat);
    outOfQuad = sum(~validPred);
    validMask = validPred & ~isundefined(qTrueCat);

    if sum(validMask) > 0
        qConfMat = confusionmat(qTrueCat(validMask), qPredCat(validMask));
    else
        qConfMat = zeros(nQPos);
    end

    qConfMatPct = zeros(size(qConfMat));
    for i = 1:size(qConfMat, 1)
        rowSum = sum(qConfMat(i,:));
        if rowSum > 0
            qConfMatPct(i,:) = qConfMat(i,:) / rowSum * 100;
        end
    end

    figure('Name', sprintf('HierClass - %s Position Confusion', quadrants(q).name), ...
        'Position', [50+q*30 50+q*30 900 800]);
    imagesc(qConfMatPct);
    navyRGB = [0.106 0.165 0.290]; tealRGB = [0.051 0.486 0.561]; whiteRGB = [1 1 1];
    n = 256; cmap = zeros(n, 3);
    for ci = 1:n, t = (ci-1)/(n-1); if t < 0.5, frac = t/0.5; cmap(ci,:) = navyRGB*(1-frac) + tealRGB*frac; else, frac = (t-0.5)/0.5; cmap(ci,:) = tealRGB*(1-frac) + whiteRGB*frac; end; end
    colormap(gca, cmap);
    cbar = colorbar;
    cbar.Label.String = 'Prediction Rate (%)';
    cbar.Label.Color = [1 1 1]; cbar.Color = [1 1 1];
    caxis([0 100]);
    set(gcf, 'Color', [0.106 0.165 0.290]);
    set(gca, 'Color', [0.106 0.165 0.290], 'XColor', [1 1 1], 'YColor', [1 1 1]);
    set(gca, 'XTick', 1:nQPos, 'XTickLabel', uniqueQ, 'XTickLabelRotation', 90);
    set(gca, 'YTick', 1:nQPos, 'YTickLabel', uniqueQ);
    xlabel('PREDICTED Position', 'FontWeight', 'bold', 'Color', [1 1 1]);
    ylabel('TRUE Position', 'FontWeight', 'bold', 'Color', [1 1 1]);

    qPosAcc = mean(posCorrect(qMask)) * 100;
    title(sprintf('%s Position Confusion | Acc=%.1f%% | %d out-of-quad', ...
        quadrants(q).name, qPosAcc, outOfQuad), 'FontWeight', 'bold', 'Color', [1 1 1]);

    for i = 1:size(qConfMatPct, 1)
        for j = 1:size(qConfMatPct, 2)
            if qConfMatPct(i,j) > 0
                if qConfMatPct(i,j) > 50, txtColor = [0.106 0.165 0.290]; else, txtColor = [1 1 1]; end
                text(j, i, sprintf('%.0f', qConfMatPct(i,j)), ...
                    'HorizontalAlignment', 'center', 'FontSize', 7, ...
                    'Color', txtColor, 'FontWeight', 'bold');
            end
        end
    end
    hold on;
    plot([0.5 nQPos+0.5], [0.5 nQPos+0.5], 'Color', [0.051 0.486 0.561], 'LineStyle', '--', 'LineWidth', 1.5);
    hold off;

    diagCorr = sum(diag(qConfMat));
    totalQ = sum(qConfMat(:));
    fprintf('  %s: %d/%d correct in-quad (%.1f%%), %d out-of-quad predictions\n', ...
        quadrants(q).name, diagCorr, totalQ, diagCorr/max(totalQ,1)*100, outOfQuad);
end

%% 8A. QUADRANT SPATIAL ACCURACY MAP
