%% 8B. SPATIAL ACCURACY MAP
fprintf('\n--- 8B. Spatial Accuracy Map ---\n');

% Auto-rebuild if needed
if ~exist('XTest', 'var')
    XTest = TrainingFeatures(:,:,:,testMask);
end
if ~exist('posLabelTest', 'var')
    posLabelTest = posLabelAll(testMask);
end

% Build coordinate lookup: position label -> (x, y)
posCoordMap = containers.Map();
for q = 1:4
    for pi = 1:length(positionLabelsPerQuad{q})
        lbl = positionLabelsPerQuad{q}{pi};
        coords = positionCoordsPerQuad{q}(pi, :);
        posCoordMap(lbl) = coords;
    end
end

% Get hierarchical predictions for all test samples
nTest = size(XTest, 4);
predLabels = cell(nTest, 1);
trueLabels = posLabelTest;

for s = 1:nTest
    testSample = XTest(:,:,:,s);
    % Stage 1: classify quadrant
    quadProbs = predict(coarseNet, testSample);
    [~, qIdx] = max(quadProbs);
    % Stage 2: classify position within quadrant
    posProbs = predict(quadrantNets{qIdx}, testSample);
    [~, posIdx] = max(posProbs);
    predLabels{s} = positionLabelsPerQuad{qIdx}{posIdx};
end

% Compute per-position accuracy
allUniquePos = unique(trueLabels);
nPos = length(allUniquePos);
posAccuracy = zeros(nPos, 1);
posCoords = zeros(nPos, 2);
posMispredict = cell(nPos, 1);
posMispredCoords = cell(nPos, 1);

for p = 1:nPos
    lbl = allUniquePos{p};
    if posCoordMap.isKey(lbl)
        posCoords(p, :) = posCoordMap(lbl);
    end
    mask = strcmp(trueLabels, lbl);
    trueCount = sum(mask);
    if trueCount > 0
        correctCount = sum(mask & strcmp(predLabels, lbl));
        posAccuracy(p) = correctCount / trueCount * 100;

        % Most common misprediction
        wrongMask = mask & ~strcmp(predLabels, lbl);
        if any(wrongMask)
            wrongPreds = predLabels(wrongMask);
            [uniqueWrong, ~, ic] = unique(wrongPreds);
            counts = accumarray(ic, 1);
            [~, maxIdx] = max(counts);
            posMispredict{p} = uniqueWrong{maxIdx};
            if posCoordMap.isKey(uniqueWrong{maxIdx})
                posMispredCoords{p} = posCoordMap(uniqueWrong{maxIdx});
            end
        end
    end
end

