quadBounds = {[1 1 2 2], [3 1 2 2], [1 3 2 2], [3 3 2 2]}; % [x y w h] in grid coords
for q = 1:4
    rectangle('Position', quadBounds{q}, 'EdgeColor', [0.051 0.486 0.561], ...
        'LineWidth', 1.5, 'LineStyle', '--');
end

% Plot each position
for p = 1:nPos
    px = posCoords(p, 1);
    py = posCoords(p, 2);
    acc = posAccuracy(p);

    % Skip if coordinates not found
    if px == 0 && py == 0, continue; end

    % Color based on accuracy
    if acc >= 100
        dotColor = [1 1 1];           % white
    elseif acc >= 80
        dotColor = [0.051 0.486 0.561]; % teal
    elseif acc >= 50
        dotColor = [0.953 0.612 0.071]; % orange
    else
        dotColor = [0.906 0.298 0.235]; % red
    end

    % Draw filled circle
    plot(px, py, 'o', 'MarkerSize', 14, 'MarkerFaceColor', dotColor, ...
        'MarkerEdgeColor', [0.106 0.165 0.290], 'LineWidth', 1.5);

    % Accuracy text
    if acc >= 80
        txtColor = [0.106 0.165 0.290]; % navy on light dots
    else
        txtColor = [1 1 1]; % white on dark dots
    end
    text(px, py, sprintf('%.0f', acc), 'HorizontalAlignment', 'center', ...
        'VerticalAlignment', 'middle', 'FontSize', 7, 'FontWeight', 'bold', ...
        'Color', txtColor);

    % Arrow for mispredictions
    if ~isempty(posMispredCoords{p})
        mpx = posMispredCoords{p}(1);
        mpy = posMispredCoords{p}(2);
        % Draw arrow from true to most common wrong prediction
        quiver(px, py, (mpx-px)*0.7, (mpy-py)*0.7, 0, ...
            'Color', [0.906 0.298 0.235], 'LineWidth', 1.5, ...
            'MaxHeadSize', 0.8);
    end
end

