% ---- Analysis 1: S-Parameter Ablation Study ----
fprintf('=== Analysis 1: S-Parameter Ablation Study ===\n');
% Row mapping:
%   Row 1: |S11| (dB)    Row 2: angle(S11)
%   Row 3: |S21| (dB)    Row 4: angle(S21)
%   Row 5: |S12| (dB)    Row 6: angle(S12)
%   Row 7: |S22| (dB)    Row 8: angle(S22)

% Build name -> [magRow phaseRow] map from saved trace order.  Replaces
% hardcoded row indices that assumed traces were always S11,S21,S12,S22.
sParamRowMap = containers.Map('KeyType','char','ValueType','any');
if ~isempty(traceList) && size(traceList,2) >= 2
    for ii = 1:size(traceList,1)
        pname = upper(strtrim(traceList{ii,2}));
        sParamRowMap(pname) = [2*ii - 1, 2*ii];
    end
    fprintf('Ablation rows derived from traceList: %s\n', ...
            strjoin(cellfun(@(c) upper(strtrim(c)), traceList(:,2)', 'UniformOutput', false), ', '));
else
    defaults = {'S11','S21','S12','S22'};
    for ii = 1:min(4, numSParamRows/2)
        sParamRowMap(defaults{ii}) = [2*ii - 1, 2*ii];
    end
    warning('traceList unavailable — ablation assumes default S11,S21,S12,S22 order.');
end

allRows  = 1:numSParamRows;
rowsFor  = @(name) sParamRowMap(name);
excludeS = @(name) setdiff(allRows, rowsFor(name));
onlyS    = @(names) sort([rowsFor(names{1}), rowsFor(names{2})]);

ablationConfigs = {
    'All S-params',      allRows;
    'Magnitude only',    1:2:numSParamRows;
    'Phase only',        2:2:numSParamRows;
};
namedSParams = keys(sParamRowMap);
for ii = 1:numel(namedSParams)
    nm = namedSParams{ii};
    ablationConfigs(end+1, :) = { sprintf('No %s', nm), excludeS(nm) };  %#ok<SAGROW>
end
pairs = { {'S21','S12'}, {'S11','S22'} };
for ii = 1:numel(pairs)
    pr = pairs{ii};
    if isKey(sParamRowMap, pr{1}) && isKey(sParamRowMap, pr{2})
        ablationConfigs(end+1, :) = { sprintf('%s+%s only', pr{1}, pr{2}), onlyS(pr) };  %#ok<SAGROW>
    end
end

nConfigs = size(ablationConfigs, 1);
ablationAccuracies = zeros(nConfigs, 1);

% Build combined position labels for overall classification accuracy
allPosLabelsCat = categorical(posLabelAll);
posLabelTrainCat = allPosLabelsCat(trainMask);
posLabelTestCat  = allPosLabelsCat(testMask);
nClassesAll = numel(categories(posLabelTrainCat));

for c = 1:nConfigs
    configName = ablationConfigs{c, 1};
    useRows    = ablationConfigs{c, 2};
    fprintf('  Testing ''%s'' (rows [%s])... ', configName, num2str(useRows));
    try
        acc = quickTrainTestClassification(XTrain, posLabelTrainCat, ...
            XTest, posLabelTestCat, useRows, numFreqPoints, nClassesAll);
        ablationAccuracies(c) = acc;
        fprintf('%.1f%%\n', acc);
    catch ME
        fprintf('FAILED: %s\n', ME.message);
        ablationAccuracies(c) = 0;
    end
end

% Bar chart with slide color scheme
