        allPosCoords = [allPosCoords; positionCoordsPerQuad{q}(i,:)]; %#ok<AGROW>
        allPosQuad(end+1) = q; %#ok<SAGROW>
    end
end

spLabels = {'Top-Left (P1)', 'Top-Right (P2)', 'Bottom-Right (P3)', 'Bottom-Left (P4)'};

