    targetLabel = allPosLabels{randPosIdx};
    targetXY    = allPosCoords(randPosIdx, :);
    targetQuad  = allPosQuad(randPosIdx);

    % Parse label for display
    tok = regexp(targetLabel, 'R(\d+)C(\d+)P(\d+)', 'tokens');
    rr = str2double(tok{1}{1});
    cc = str2double(tok{1}{2});
    pp = str2double(tok{1}{3});
    targetDisplayName = sprintf('Row %d, Col %d, %s', rr, cc, spLabels{pp});

    fprintf('\n============================================\n');
    fprintf('  Place the rod at: %s\n', targetDisplayName);
    fprintf('  Label: %s | Quadrant: %s | Physical: (%.3f, %.3f) in\n', ...
        targetLabel, quadrants(targetQuad).name, targetXY(1), targetXY(2));
