    % Take measurement
    fprintf('Measuring...');
    liveMeas = readSParameters(vna);
    liveFeature = liveMeas - diagBaseline;
    liveInput = reshape(liveFeature, [8, numFreqPoints, 1, 1]);
    fprintf(' Done!\n');

    % Stage 1: classify quadrant
    quadProbs = predict(coarseNet, liveInput);
    [quadConf, quadChoice] = max(quadProbs);

    fprintf('\n  Quadrant: %s (%.0f%% confidence)', ...
        quadrants(quadChoice).name, quadConf * 100);
    if quadChoice == targetQuad
        fprintf(' [CORRECT]\n');
    else
        fprintf(' [WRONG - should be %s]\n', quadrants(targetQuad).name);
    end

    % Stage 2: classify position within chosen quadrant
    posProbs = predict(quadrantNets{quadChoice}, liveInput);
    [posConf, posIdx] = max(posProbs);
    predictedLabel = positionLabelsPerQuad{quadChoice}{posIdx};

    % Top 3 candidates
    [sortedProbs, sortedIdx] = sort(posProbs, 'descend');
    fprintf('  Quadrant: %s (%.0f%%) -> Position: %s (%.0f%%)\n', ...
        quadrants(quadChoice).name, quadConf*100, predictedLabel, posConf*100);
    fprintf('  Top 3 candidates:\n');
    for k = 1:min(3, length(sortedIdx))
        candLabel = positionLabelsPerQuad{quadChoice}{sortedIdx(k)};
        fprintf('    %d. %s (%.1f%%)\n', k, candLabel, sortedProbs(k)*100);
    end

    % Check correctness
    if strcmp(predictedLabel, targetLabel)
        fprintf('  Result: CORRECT\n');
    else
        fprintf('  Result: WRONG (predicted %s, true %s)\n', predictedLabel, targetLabel);
    end

    % Quadrant probabilities
    fprintf('  Quadrant probabilities: ');
