        % Show quadrant confidence text
        for q = 1:4
            if q == quadChoice
                txtColor = quadColors{q};
                fw = 'bold';
            else
                txtColor = [0.7 0.7 0.7];
                fw = 'normal';
            end
            text(quadCenters(q,1), quadCenters(q,2), ...
                sprintf('%s\n%.0f%%', quadNames{q}, avgQuadProbs(q)*100), ...
                'Color', txtColor, 'FontSize', 12, 'HorizontalAlignment', 'center', ...
                'FontWeight', fw);
        end

        axis([0 6 0 6]); axis equal;
        xlabel('X (inches)');
        ylabel('Y (inches)');
        title(sprintf('LIVE #%d (avg %d) | %s (%.0f%%) | %s (%.0f%%)', ...
            sweepCount, min(sweepCount, rollingAvgWindow), ...
            quadrants(quadChoice).name, quadConf*100, ...
            predictedLabel, posConfidence*100), 'FontWeight', 'bold');
        hold off;
        drawnow;

    catch ME
        fprintf('Error: %s\n', ME.message);
        pause(0.5);
    end
end

fprintf('Live prediction ended.\n');
clear vna;

%% ===== LOCAL FUNCTIONS =====

function sParams = readSParameters(vna)
    traceList = { 'CH1_S11_1', 'S11'; ...
                  'CH1_S21_4', 'S21'; ...
                  'CH1_S12_2', 'S12'; ...
                  'CH1_S22_3', 'S22' };
    sParams = [];
    writeline(vna, ':FORM:DATA ASC,0');
    for k = 1:4
        writeline(vna, sprintf(':CALC1:PAR:SEL ''%s''', traceList{k,1}));
        writeline(vna, ':CALC1:DATA? SDATA');
        dataStr = readline(vna);
        rawData = str2double(strsplit(char(dataStr), ','));
        realPart = rawData(1:2:end);
        imagPart = rawData(2:2:end);
        complexData = realPart + 1j * imagPart;
        magDB    = 20 * log10(abs(complexData) + eps);
        phaseRad = angle(complexData);
        sParams  = [sParams; magDB; phaseRad]; %#ok<AGROW>
    end
end

function errRate = trainEvalClassifier(params, XTrain, YTrain, XTest, YTest, numFreqPoints, maxEpochs)
% Used by bayesopt for Stage 1 quadrant classifier optimization
    try
        layers = [
            imageInputLayer([8 numFreqPoints 1], 'Normalization', 'zscore', 'Name', 'input')
            convolution2dLayer([4 20], params.Conv1Filters, 'Padding', 'same', 'Name', 'conv1')
            batchNormalizationLayer('Name', 'bn1')
            reluLayer('Name', 'relu1')
            convolution2dLayer([2 10], params.Conv2Filters, 'Padding', 'same', 'Name', 'conv2')
            batchNormalizationLayer('Name', 'bn2')
            reluLayer('Name', 'relu2')
            fullyConnectedLayer(params.FC1Neurons, 'Name', 'fc1')
            batchNormalizationLayer('Name', 'bn3')
            reluLayer('Name', 'relu3')
            dropoutLayer(params.Dropout1, 'Name', 'dropout')
            fullyConnectedLayer(4, 'Name', 'fc_out')
            softmaxLayer('Name', 'softmax')
            classificationLayer('Name', 'output')
        ];
        options = trainingOptions('adam', ...
            'MaxEpochs', maxEpochs, ...
            'MiniBatchSize', params.MiniBatchSize, ...
            'InitialLearnRate', params.InitialLearnRate, ...
            'Shuffle', 'every-epoch', ...
            'Verbose', false, ...
            'Plots', 'none', ...
            'ExecutionEnvironment', 'auto');
        tempNet = trainNetwork(XTrain, YTrain, layers, options);
        predLabels = classify(tempNet, XTest);
        acc = mean(predLabels == YTest);
        errRate = 1 - acc;
        fprintf('  Trial accuracy: %.1f%%\n', acc * 100);
    catch ME
        fprintf('  Trial FAILED: %s\n', ME.message);
        errRate = 1;
    end
end

function objective = trainEvalQuadClassifier(params, xTr, yTr, xTe, yTe, nFreq, maxEp)
% Used by bayesopt for Stage 2 per-quadrant position classifier optimization
    nClasses = numel(categories(yTr));
    layers = [
        imageInputLayer([8 nFreq 1], 'Normalization', 'zscore', 'Name', 'input')
        convolution2dLayer([4 20], params.Conv1Filters, 'Padding', 'same', 'Name', 'conv1')
        batchNormalizationLayer('Name', 'bn1')
        reluLayer('Name', 'relu1')
        convolution2dLayer([2 10], params.Conv2Filters, 'Padding', 'same', 'Name', 'conv2')
        batchNormalizationLayer('Name', 'bn2')
        reluLayer('Name', 'relu2')
        fullyConnectedLayer(params.FC1Neurons, 'Name', 'fc1')
        batchNormalizationLayer('Name', 'bn3')
        reluLayer('Name', 'relu3')
        dropoutLayer(params.Dropout1, 'Name', 'dropout')
        fullyConnectedLayer(nClasses, 'Name', 'fc_out')
        softmaxLayer('Name', 'softmax')
        classificationLayer('Name', 'output')
    ];
    opts = trainingOptions('adam', ...
        'MaxEpochs', maxEp, ...
        'MiniBatchSize', params.MiniBatchSize, ...
        'InitialLearnRate', params.InitialLearnRate, ...
        'Shuffle', 'every-epoch', ...
        'Verbose', false, ...
        'Plots', 'none', ...
        'ExecutionEnvironment', 'auto');
    try
        net = trainNetwork(xTr, yTr, layers, opts);
        acc = mean(classify(net, xTe) == yTe);
        objective = 1 - acc;  % minimize (1 - accuracy)
        fprintf('  Trial accuracy: %.1f%%\n', acc * 100);
    catch ME
        fprintf('  Trial FAILED: %s\n', ME.message);
        objective = 1;
    end
end

function acc = quickTrainTestClassification(XTr, YTr, XTe, YTe, useRows, nFreq, nClasses)
% Quick ablation training for classification: train CNN, report accuracy
    xTr = XTr(useRows, :, :, :);
    xTe = XTe(useRows, :, :, :);
    nRows = length(useRows);
    layers = [
        imageInputLayer([nRows nFreq 1], 'Normalization', 'zscore')
        convolution2dLayer([min(4, nRows) min(20, nFreq)], 32, 'Padding', 'same')
        batchNormalizationLayer
        reluLayer
        convolution2dLayer([min(2, nRows) min(10, nFreq)], 32, 'Padding', 'same')
        batchNormalizationLayer
        reluLayer
        fullyConnectedLayer(64)
        batchNormalizationLayer
        reluLayer
        dropoutLayer(0.3)
        fullyConnectedLayer(nClasses)
        softmaxLayer
        classificationLayer
    ];
    if gpuDeviceCount > 0
        execEnvAbl = 'gpu';
    else
        execEnvAbl = 'cpu';
    end
    opts = trainingOptions('adam', 'MaxEpochs', 20, 'MiniBatchSize', 16, ...
        'Shuffle', 'every-epoch', 'Verbose', false, 'Plots', 'none', ...
        'ExecutionEnvironment', execEnvAbl);
    try
        net = trainNetwork(xTr, YTr, layers, opts);
        preds = classify(net, xTe);
        acc = mean(preds == YTe) * 100;
    catch ME
        warning('quickTrainTestClassification failed: %s', ME.message);
        acc = 0;
    end
end
